import api from './api';

const walletService = {
  getSummary: (params) => api.get('/wallet/summary', { params }),
  getTransactions: (params) => api.get('/wallet/transactions', { params }),
  postRefund: (data) => api.post('/wallet/refund', data),
};

export default walletService;
